<?php
/**
 * WP Safe Mode AI — fatal error handler drop-in.
 *
 * Do not edit this file directly. It is generated from
 * mu-loader/fatal-error-handler.php inside the plugin, with the storage path
 * substituted at install time, and replaced wholesale on update.
 *
 * This file is included by wp_register_fatal_error_handler() before the
 * database, the options API, or any plugin has loaded. It therefore cannot use
 * $wpdb, get_option(), or the toolkit's autoloader. Everything it needs is read
 * from a flat JSON file whose absolute path is baked in below.
 *
 * If it cannot do its job for any reason it hands straight back to core's
 * handler. A recovery mechanism that can itself fail loudly is worse than none.
 *
 * @package WPSM
 */

defined( 'ABSPATH' ) || exit;

if ( ! class_exists( 'WP_Fatal_Error_Handler' ) ) {
	return null;
}

if ( ! class_exists( 'WPSM_Fatal_Error_Handler' ) ) {

	/**
	 * Restores the last file change when it looks responsible for a fatal.
	 */
	class WPSM_Fatal_Error_Handler extends WP_Fatal_Error_Handler {

		/**
		 * Absolute path to the pending-change mirror, substituted at install.
		 */
		const PENDING_FILE = '{{WPSM_PENDING_FILE}}';

		/**
		 * Absolute path to the snapshots directory, substituted at install.
		 */
		const SNAPSHOT_DIR = '{{WPSM_SNAPSHOT_DIR}}';

		/**
		 * A change older than this is no longer a candidate for auto-revert.
		 *
		 * Without a bound, a fatal weeks later would roll back an unrelated
		 * edit that has been working fine the whole time.
		 */
		const MAX_AGE = 600;

		/**
		 * Below this age, a fatal we cannot attribute to a specific file is
		 * still assumed to be ours if exactly one change is in flight — a
		 * syntax error in an included file surfaces in the includer, so the
		 * reported path often is not the one we touched.
		 */
		const BLAME_WINDOW = 120;

		/**
		 * Shutdown handler.
		 */
		public function handle() {
			try {
				$this->attempt_recovery();
			} catch ( Throwable $e ) {
				// Swallow. Whatever went wrong here, core's handler still needs
				// to run and the user still needs to see a page.
				$this->record_failure( $e->getMessage() );
			}

			parent::handle();
		}

		/**
		 * Look for a pending change that explains the current fatal, and undo it.
		 */
		private function attempt_recovery() {
			$error = error_get_last();

			if ( ! is_array( $error ) || ! $this->is_fatal( $error ) ) {
				return;
			}

			$pending = $this->read_pending();

			if ( array() === $pending ) {
				return;
			}

			$now       = time();
			$fresh     = array();
			$culprit   = null;
			$error_file = isset( $error['file'] ) ? $this->normalise( (string) $error['file'] ) : '';

			foreach ( $pending as $change_id => $entry ) {
				if ( ! is_array( $entry ) || empty( $entry['files'] ) ) {
					continue;
				}

				$age = $now - (int) ( isset( $entry['opened_at'] ) ? $entry['opened_at'] : 0 );

				if ( $age > self::MAX_AGE ) {
					continue;
				}

				$fresh[ $change_id ] = $entry;

				foreach ( $entry['files'] as $file ) {
					if ( ! isset( $file['path'] ) ) {
						continue;
					}

					if ( $this->normalise( (string) $file['path'] ) === $error_file ) {
						$culprit = $change_id;
						break 2;
					}
				}
			}

			// No direct match. If exactly one change is in flight and it is very
			// recent, it is overwhelmingly likely to be the cause.
			if ( null === $culprit && 1 === count( $fresh ) ) {
				$only = array_keys( $fresh );
				$id   = $only[0];
				$age  = $now - (int) $fresh[ $id ]['opened_at'];

				if ( $age <= self::BLAME_WINDOW ) {
					$culprit = $id;
				}
			}

			if ( null === $culprit ) {
				return;
			}

			$restored = $this->restore( (string) $culprit );

			$this->drop_pending( (string) $culprit );
			$this->record_recovery( (string) $culprit, $restored, $error );
		}

		/**
		 * Restore every file captured for a change.
		 *
		 * Mirrors WPSM\Snapshots\Restore::revert(). Keep the two in step — the
		 * manifest format is the contract between them.
		 *
		 * @param string $change_id Change to roll back.
		 * @return array<int, string> Paths restored or deleted.
		 */
		private function restore( $change_id ) {
			$dir      = rtrim( self::SNAPSHOT_DIR, '/' ) . '/' . preg_replace( '/[^a-zA-Z0-9_-]/', '', $change_id );
			$manifest = $this->read_json( $dir . '/manifest.json' );

			if ( ! is_array( $manifest ) || empty( $manifest['files'] ) || ! is_array( $manifest['files'] ) ) {
				return array();
			}

			$touched = array();

			foreach ( $manifest['files'] as $file ) {
				if ( ! is_array( $file ) || empty( $file['path'] ) ) {
					continue;
				}

				$path = (string) $file['path'];

				// The change created this file; deleting it is the inverse.
				if ( empty( $file['existed'] ) ) {
					if ( is_file( $path ) && @unlink( $path ) ) {
						$touched[] = $path;
					}
					continue;
				}

				$blob = $dir . '/files/' . (int) $file['index'] . '.bin';

				if ( ! is_readable( $blob ) ) {
					continue;
				}

				$bytes = @file_get_contents( $blob );

				if ( false === $bytes ) {
					continue;
				}

				// Never write back a snapshot we cannot vouch for.
				if ( ! empty( $file['sha256'] ) && hash( 'sha256', $bytes ) !== $file['sha256'] ) {
					continue;
				}

				if ( false === @file_put_contents( $path, $bytes, LOCK_EX ) ) {
					continue;
				}

				if ( ! empty( $file['mode'] ) ) {
					@chmod( $path, (int) $file['mode'] );
				}
				if ( ! empty( $file['mtime'] ) ) {
					@touch( $path, (int) $file['mtime'] );
				}

				// The broken bytes are almost certainly cached; without this the
				// next request serves the file we just replaced.
				if ( function_exists( 'opcache_invalidate' ) && '.php' === substr( $path, -4 ) ) {
					@opcache_invalidate( $path, true );
				}

				$touched[] = $path;
			}

			return $touched;
		}

		/**
		 * @param array<string, mixed> $error
		 * @return bool
		 */
		private function is_fatal( array $error ) {
			$fatal = array( E_ERROR, E_PARSE, E_USER_ERROR, E_COMPILE_ERROR, E_CORE_ERROR, E_RECOVERABLE_ERROR );

			return isset( $error['type'] ) && in_array( (int) $error['type'], $fatal, true );
		}

		/**
		 * @return array<string, mixed>
		 */
		private function read_pending() {
			$data = $this->read_json( self::PENDING_FILE );

			return is_array( $data ) ? $data : array();
		}

		/**
		 * @param string $path
		 * @return mixed
		 */
		private function read_json( $path ) {
			if ( ! is_readable( $path ) ) {
				return null;
			}

			$raw = @file_get_contents( $path );

			if ( false === $raw || '' === $raw ) {
				return null;
			}

			return json_decode( $raw, true );
		}

		/**
		 * @param string $change_id
		 */
		private function drop_pending( $change_id ) {
			$pending = $this->read_pending();

			if ( ! isset( $pending[ $change_id ] ) ) {
				return;
			}

			unset( $pending[ $change_id ] );

			@file_put_contents(
				self::PENDING_FILE,
				json_encode( $pending, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES ),
				LOCK_EX
			);
		}

		/**
		 * Leave a note for the plugin to journal on the next healthy request.
		 *
		 * We cannot write to the database from here with any confidence, so the
		 * audit trail is completed asynchronously.
		 *
		 * @param string             $change_id Change rolled back.
		 * @param array<int, string> $restored  Paths touched.
		 * @param array<string, mixed> $error   The fatal that triggered this.
		 */
		private function record_recovery( $change_id, array $restored, array $error ) {
			$this->append_report(
				array(
					'type'       => 'auto_revert',
					'change_id'  => $change_id,
					'restored'   => $restored,
					'error_file' => isset( $error['file'] ) ? $error['file'] : null,
					'error_line' => isset( $error['line'] ) ? $error['line'] : null,
					'error_msg'  => isset( $error['message'] ) ? $error['message'] : null,
					'at'         => time(),
				)
			);
		}

		/**
		 * @param string $message
		 */
		private function record_failure( $message ) {
			$this->append_report(
				array(
					'type'    => 'handler_error',
					'message' => $message,
					'at'      => time(),
				)
			);
		}

		/**
		 * @param array<string, mixed> $report
		 */
		private function append_report( array $report ) {
			$path    = dirname( self::PENDING_FILE ) . '/recovery-reports.json';
			$reports = $this->read_json( $path );

			if ( ! is_array( $reports ) ) {
				$reports = array();
			}

			$reports[] = $report;

			// Bounded so a pathological loop cannot fill the disk.
			if ( count( $reports ) > 100 ) {
				$reports = array_slice( $reports, -100 );
			}

			@file_put_contents( $path, json_encode( $reports, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES ), LOCK_EX );
		}

		/**
		 * @param string $path
		 * @return string
		 */
		private function normalise( $path ) {
			$real = realpath( $path );

			return false !== $real ? $real : $path;
		}
	}
}

return new WPSM_Fatal_Error_Handler();
